function runFakeNTicks(shard: Shard, fakeNow: () => number, n: number): void {
  // The SimLoop reads its clock through `hooks.clock` (default
  // `performanceNow()`); tests drive that by setting the env via
  // `vi.useFakeTimers()` and advancing the system time.
  const tickMs = TICK_S * 1000;
